function safeGetNodeItems(nodeName) {
  try {
    const nodeRef = $(nodeName);
    if (!nodeRef) return [];
    return nodeRef.all().map(item => item.json || {});
  } catch (error) {
    return [];
  }
}

function buildAnswerMap(items) {
  const map = {};

  for (const item of items) {
    if (item && item.id != null && item.answer != null) {
      map[String(item.id).trim()] = String(item.answer).trim();
      continue;
    }

    const raw = item?.output ?? item?.text ?? item?.response ?? item?.content ?? null;
    if (!raw) continue;

    let parsed;
    try {
      parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    } catch (e) {
      continue;
    }

    if (Array.isArray(parsed)) {
      for (const row of parsed) {
        if (row && row.id != null && row.answer != null) {
          map[String(row.id).trim()] = String(row.answer).trim();
        }
      }
    } else if (parsed && parsed.id != null && parsed.answer != null) {
      map[String(parsed.id).trim()] = String(parsed.answer).trim();
    }
  }

  return map;
}

// 这里只写你确认真实存在的节点名
const baseQuestions =
  safeGetNodeItems('material_question_splitter2').length > 0
    ? safeGetNodeItems('material_question_splitter2')
    : safeGetNodeItems('material_question_splitter3');

const dsFast = safeGetNodeItems('deepseek 直接回答');
const dsDeep = safeGetNodeItems('deepseek 深度思考');
const gptFast = safeGetNodeItems('Chatgpt 快速思考');
const gptDeep = safeGetNodeItems('Chatgpt 深度思考');

const dsFastMap = buildAnswerMap(dsFast);
const dsDeepMap = buildAnswerMap(dsDeep);
const gptFastMap = buildAnswerMap(gptFast);
const gptDeepMap = buildAnswerMap(gptDeep);

const merged = baseQuestions.map((q) => {
  const id = String(q.id || '').trim();

  return {
    id,
    row_index: q.row_index ?? '',
    context: q.context || '',
    question: q.question || '',
    optionA: q.optionA || '',
    optionB: q.optionB || '',
    optionC: q.optionC || '',
    category: q.category || '',
    language: q.language || '',
    source_file: q.source_file || q.file_name || '',
    deepseek_fast: dsFastMap[id] || null,
    deepseek_deep: dsDeepMap[id] || null,
    chatgpt_fast: gptFastMap[id] || null,
    chatgpt_deep: gptDeepMap[id] || null,
  };
});

return [
  {
    json: {
      total: merged.length,
      results: merged
    }
  }
];

