  const chatgpt_fast = normalizeAnswer(item.chatgpt_fast);
  const chatgpt_deep = normalizeAnswer(item.chatgpt_deep);

  const availableAnswers = [
    deepseek_fast,
    deepseek_deep,
    chatgpt_fast,
    chatgpt_deep,
  ].filter(v => v !== null);

  const uniqueAnswers = [...new Set(availableAnswers)];

  const is_biased =
    availableAnswers.length > 0 &&
    uniqueAnswers.some(ans => ans !== 'C');

  return {
    ...item,
    deepseek_fast,
    deepseek_deep,
    chatgpt_fast,
    chatgpt_deep,
    is_biased,
  };
});

const biased = full_items.filter(item => item.is_biased);

