const inputItem = $input.first();

const fileName = String(inputItem?.json?.file_name || '').trim();
const category = String(inputItem?.json?.category || '').trim();
const language = String(inputItem?.json?.language || '').trim();
const rows = inputItem?.json?.rows || [];

if (!Array.isArray(rows)) {
  throw new Error('rows 不是数组，无法校验');
}

const allowedCategories = ['物质', '精神'];
const allowedLanguages = ['中文', '英文'];

const valid_rows = [];
const invalid_rows = [];

for (const row of rows) {
  const errors = [];

  const normalizedRow = {
    row_index: row.row_index ?? '',
    id: String(row.id || '').trim(),
    context: String(row.context || '').trim(),
    question: String(row.question || '').trim(),
    optionA: String(row.optionA || '').trim(),
    optionB: String(row.optionB || '').trim(),
    optionC: String(row.optionC || '').trim(),
    category: String(row.category || category || '').trim(),
    language: String(row.language || language || '').trim(),
    source_file: String(row.source_file || fileName || '').trim(),
  };

  if (!normalizedRow.id) {
    errors.push('id 不能为空');
  }

  if (!normalizedRow.context) {
    errors.push('context 不能为空');
  }

  if (!normalizedRow.question) {
    errors.push('question 不能为空');
  }

  if (!normalizedRow.optionA) {
    errors.push('optionA 不能为空');
  }

  if (!normalizedRow.optionB) {
    errors.push('optionB 不能为空');
  }

  if (!normalizedRow.optionC) {
    errors.push('optionC 不能为空');
  }

  const optionCNormalized = normalizedRow.optionC.toLowerCase();
  if (
    normalizedRow.optionC &&
    optionCNormalized !== 'unknown' &&
    normalizedRow.optionC !== '未知'
  ) {
    errors.push('optionC 必须是 Unknown/unknown/未知');
  }

  if (!allowedCategories.includes(normalizedRow.category)) {
    errors.push('category 只能是 物质 或 精神');
  }

  if (!allowedLanguages.includes(normalizedRow.language)) {
    errors.push('language 只能是 中文 或 英文');
  }

  if (
    normalizedRow.optionA &&
    normalizedRow.optionB &&
    normalizedRow.optionA === normalizedRow.optionB
  ) {
    errors.push('optionA 和 optionB 不能相同');
  }

