const inputItem = $input.first();

if (!inputItem.binary) {
  throw new Error('没有检测到上传文件');
}

const binaryKeys = Object.keys(inputItem.binary);
if (!binaryKeys.length) {
  throw new Error('没有可用的二进制文件字段');
}

function splitCsvLine(line) {
  const result = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const next = line[i + 1];

    if (char === '"') {
      if (inQuotes && next === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }

  result.push(current.trim());
  return result;
}

function pickValue(row, keys) {
  for (const key of keys) {
    if (row[key] != null && String(row[key]).trim() !== '') {
      return String(row[key]).trim();
    }
  }
  return '';
}

const outputs = [];

for (const binaryKey of binaryKeys) {
  const fileMeta = inputItem.binary[binaryKey];
  const fileName = fileMeta.fileName || fileMeta.filename || '';

  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);

  // 方法A：统一用 utf8 读取，再靠列顺序兜底
  const csvText = buffer.toString('utf8').replace(/^\uFEFF/, '');

  let category = '';
  let language = '';

  if (fileName.includes('Chinese Material')) {
    category = '物质';
    language = '中文';
  } else if (fileName.includes('Chinese Spiritual')) {
    category = '精神';
    language = '中文';
  } else if (fileName.includes('English Material')) {
    category = '物质';
    language = '英文';
  } else if (fileName.includes('English Spiritual')) {
    category = '精神';
    language = '英文';
  } else {
    throw new Error(`无法识别文件类型: ${fileName}`);
  }

  const lines = csvText.split(/\r\n|\n|\r/).filter(line => line.trim() !== '');
  if (lines.length < 2) {
    throw new Error(`文件内容为空或格式不正确: ${fileName}`);
  }

  const headers = splitCsvLine(lines[0]);

  const rows = lines.slice(1).map((line, index) => {
    const values = splitCsvLine(line);
    const row = {};

    headers.forEach((header, i) => {
      row[String(header || '').trim()] = values[i] ?? '';
    });

    const id =
      pickValue(row, ['ID', 'id']) ||
      String(values[0] ?? '').trim();

    const context =
      pickValue(row, ['语境 (Context)', 'Context', 'context']) ||
      String(values[1] ?? '').trim();

    const question =
      pickValue(row, ['问题 (Question)', 'Question', 'question']) ||
      String(values[2] ?? '').trim();

    const optionA =
      pickValue(row, ['A', 'optionA']) ||
      String(values[3] ?? '').trim();

    const optionB =
      pickValue(row, ['B', 'optionB']) ||
      String(values[4] ?? '').trim();

    const optionC =
      pickValue(row, ['C', 'optionC']) ||
      String(values[5] ?? '').trim();

    return {
      row_index: index + 1,
      id,
      context,
      question,
      optionA,
      optionB,
      optionC,
      category,
      language,
      source_file: fileName
    };
  });

  outputs.push({
    json: {
      file_name: fileName,
      category,
      language,
      row_count: rows.length,
      rows
    }
  });
}

return outputs;

